    result = []
    for i, c in enumerate(s):
        if c.isupper() and i > 0:
            if s[i-1].islower() and (i == len(s)-1 or not s[i+1].isupper()): 
                result.append('_')
        result.append(c.lower())
    return ''.join(result)

